<template>
    <div class="container" style="max-width:560px">
        <div class="row pt-4 verticalh-100 fondo-3 pb-5">
            <div class="col-lg-12">
                <h1 class="text-center cursiva">Confirma tu Asistencia</h1>
                <div class="row" v-for="(item,index) in ListaInvitados" :key="index">
                    <div class="col-12">
                        <label class="container-check fuente-generica">{{item.Nombre}}
                            <input :id="'checkinvitado'+item.Id" type="checkbox" v-model="item.Check" @change="CambiarEstatus(index)"> 
                            <span class="checkmark"></span>
                        </label>
                    </div>
                </div>
                <div class="row">
                    <div class="col-12 d-flex justify-content-center">
                        <button type="button" @click="Guardar()" class="btn btn-maps text-center">Confirmar</button>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
export default {
    name:'confirmacion',
    data() {
        return {
            ListaInvitados:[]
        }
    },
    methods: {
        async GetListaInvitados(){
            await this.$http.get('invitados/List').then((res) => {
                // console.log(res.data);
                this.ListaInvitados=res.data;
                this.ListaInvitados.forEach(element => {
                    if (element.Estatus==1) {
                        element.Check=true;   
                    }
                    else{
                        element.Check=false;
                    }
                });
            }).finally(()=>{
                this.ListaInvitados.forEach(element=>{
                    if (element.Estatus==1) {
                        let CheckInput=document.getElementById("checkinvitado"+element.Id);
                        CheckInput.disabled=true;
                    }
                })
            })
        },
        async Guardar(){
            this.$swal({
                title:"<strong>¿Confirma su Asistencia?</strong>",
                icon:"question",
                showCloseButton:true,
                showCancelButton:true,
                confirmButtonText:'Confirmar',
                cancelButtonText:'Cancelar'
            }).then((res) => {
                // console.log(res);
                if (res.isConfirmed===true) {
                    let formData=new FormData();
                    formData.set('ArrayInvitados',JSON.stringify(this.ListaInvitados));
                    this.$http.post('invitados/ModifyStatus',formData).then((res)=>{
                        console.log(res);
                        this.$router.push({name:'Contacto'})
                    })
                }
            })
        },
        CambiarEstatus(index){
            if (this.ListaInvitados[index].Check!==false) {
                this.ListaInvitados[index].Estatus=1;   
            }
            else{
                this.ListaInvitados[index].Estatus=0;
            }
            // console.log(this.ListaInvitados[index].Check);
        }
    },
    mounted() {
        this.GetListaInvitados();
    },
}
</script>

