<template>
  <span
    class="svg-icon"
    v-html="svgContent"
    v-bind="$attrs"
  />
</template>

<script>
export default {
  name: 'SvgIcon',

  inheritAttrs: false,

  props: {
    src: {
      type: String,
      required: true
    }
  },

  data() {
    return {
      svgContent: ''
    }
  },

  watch: {
    src: {
      immediate: true,
      handler() {
        this.loadSvg()
      }
    }
  },

  methods: {
    async loadSvg() {
      try {
        const response = await fetch(this.src)
        this.svgContent = await response.text()
      } catch (e) {
        console.error(e)
      }
    }
  }
}
</script>

<style scoped>
.svg-icon {
  display: inline-flex;
}
</style>

<style>
/* Hace que el SVG ocupe el tamaño del contenedor */
.svg-icon svg {
  width: 100%;
  height: 100%;
}
</style>