import Vue from "vue";
import VueRouter from "vue-router";
import Invitacion from "@/views/Invitacion.vue";
import Confirmacion from "@/views/Confirmacion.vue";
import Contacto from "@/views/Contacto.vue";
Vue.use(VueRouter);
const routes=[
    {
        path:"/",
        name:"Invitacion",
        component:Invitacion,
        props:true
    },
    {
        path:"/confirmacion",
        name:"Confirmacion",
        component:Confirmacion,
        props:true
    },
    {
        path:"/contacto",
        name:"Contacto",
        component:Contacto,
        props:true
    }
];
const router = new VueRouter({
	mode: 'history',
    base: process.env.BASE_URL,
	routes
});
export default router;